package br.com.onda;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.widget.*;
import androidx.media3.common.*;
import androidx.media3.session.MediaController;
import androidx.media3.session.*;
import com.google.common.util.concurrent.ListenableFuture;
import java.io.*;
import java.lang.reflect.Field;
import java.util.concurrent.TimeUnit;
import org.junit.*;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;

/** Deterministic real decoder/service tests. Provider extraction availability is not simulated as success. */
@androidx.media3.common.util.UnstableApi
public class YouTubeAudioTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();
 private static final String SOURCE="https://www.youtube.com/watch?v=aqz-KE-bpKQ";
 private YouTubeActivity activity;private Activity anchor;private MediaController player;private ListenableFuture<MediaController> connection;private File audio;private YouTubeAudioPlayback.Resolver original;
 private Object field(String name)throws Exception{Field f=YouTubeActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{for(int n=0;n<300;n++){boolean[] ok={false};ins.runOnMainSync(()->{try{ok[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(ok[0])return;Thread.sleep(50);}String[] state={"not connected"};ins.runOnMainSync(()->{if(player!=null&&player.isConnected())state[0]="state="+player.getPlaybackState()+" playing="+player.isPlaying()+" ready="+player.getPlayWhenReady()+" repeat="+player.getRepeatMode()+" position="+player.getCurrentPosition()+" duration="+player.getDuration()+" source="+YouTubeAudio.source(player.getCurrentMediaItem());});fail("Native YouTube audio did not reach expected state: "+state[0]);}
 private void shell(String command)throws Exception{try(ParcelFileDescriptor p=ins.getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){while(in.read()!=-1){}}}
 @Before public void setup()throws Exception{original=YouTubeAudioPlayback.resolver;anchor=ins.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->anchor.hasWindowFocus());YouTubeAudio.clear(c);audio=AudioTestFixtures.tone(c,45000);ins.runOnMainSync(()->connection=new MediaController.Builder(c,new SessionToken(c,new ComponentName(c,PlaybackService.class))).buildAsync());player=connection.get(15,TimeUnit.SECONDS);ins.runOnMainSync(()->{player.setRepeatMode(Player.REPEAT_MODE_OFF);player.setMediaItem(new MediaItem.Builder().setMediaId("previous-local-fixture").setUri(Uri.fromFile(audio)).build());player.prepare();player.play();});waitFor(()->player.isPlaying());}
 private void launch()throws Exception{activity=(YouTubeActivity)ins.startActivitySync(new Intent(c,YouTubeActivity.class).putExtra(YouTubeFavorites.EXTRA,SOURCE).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->field("web")!=null&&activity.hasWindowFocus()&&((android.webkit.WebView)field("web")).getWidth()>0&&((Button)field("listenAudio")).isEnabled());ins.runOnMainSync(()->{android.webkit.WebView web=(android.webkit.WebView)unchecked("web");web.stopLoading();web.loadDataWithBaseURL(SOURCE,"<html><head><title>Audio fixture</title></head><body>Native audio test</body></html>","text/html","UTF-8",SOURCE);});waitFor(()->((android.webkit.WebView)field("web")).getProgress()==100);}
 private Object unchecked(String name){try{return field(name);}catch(Exception e){throw new RuntimeException(e);}}
 private void click(){ins.runOnMainSync(()->((Button)unchecked("listenAudio")).performClick());}
 @After public void after()throws Exception{shell("input keyevent 224");shell("wm dismiss-keyguard");ins.runOnMainSync(()->{if(activity!=null)activity.finish();if(anchor!=null)anchor.finish();if(player!=null){player.pause();player.stop();player.clearMediaItems();player.setRepeatMode(Player.REPEAT_MODE_OFF);}if(connection!=null)MediaController.releaseFuture(connection);});ins.waitForIdleSync();YouTubeAudio.clear(c);c.getSharedPreferences("music_resume",0).edit().clear().commit();YouTubeAudioPlayback.resolver=original;if(audio!=null)audio.delete();}
 @Test public void selectedAudioKeepsPlayingScreenOffAndControlsNeverResumeOldMusic()throws Exception{
  YouTubeAudioPlayback.resolver=source->YouTubeAudio.item(source,"YouTube audio fixture",Uri.fromFile(audio).toString(),"audio/wav");launch();waitFor(()->!player.getPlayWhenReady());
  c.getSharedPreferences("music_resume",0).edit().putString("queue","[\"42\"]").putLong("position",12345).commit();click();waitFor(()->YouTubeAudio.is(player.getCurrentMediaItem())&&player.isPlaying()&&player.getCurrentPosition()>250);
  ins.runOnMainSync(()->{assertEquals(SOURCE,YouTubeAudio.source(player.getCurrentMediaItem()));assertEquals(1,player.getMediaItemCount());assertEquals("[\"42\"]",c.getSharedPreferences("music_resume",0).getString("queue",""));assertEquals(12345,c.getSharedPreferences("music_resume",0).getLong("position",0));});
  long[] at={0};ins.runOnMainSync(()->at[0]=player.getCurrentPosition());shell("input keyevent 223");Thread.sleep(2200);ins.runOnMainSync(()->{assertFalse(((PowerManager)c.getSystemService(Context.POWER_SERVICE)).isInteractive());assertTrue(player.isPlaying());assertTrue(player.getCurrentPosition()>at[0]+1000);assertTrue(YouTubeAudio.is(player.getCurrentMediaItem()));assertFalse(activity.isInPictureInPictureMode());assertNull(unchecked("web"));player.pause();});waitFor(()->!player.isPlaying());ins.runOnMainSync(()->player.play());waitFor(()->player.isPlaying());ins.runOnMainSync(()->assertEquals(SOURCE,YouTubeAudio.source(player.getCurrentMediaItem())));
  assertFalse(c.getSharedPreferences("youtube_audio",0).getAll().toString().contains(audio.getAbsolutePath()));
  try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"youtube-native-audio.json"))){out.write("{\"realDecoderAndService\":true,\"screenOffContinues\":true,\"sameVideoAfterTransportPlay\":true,\"localQueuePreserved\":true,\"webViewDestroyed\":true,\"noAutomaticPip\":true,\"providerAvailabilityTested\":false}".getBytes("UTF-8"));}
 }
 @Test public void extractionFailureLeavesOldMusicPausedAndWritesReport()throws Exception{YouTubeAudioPlayback.resolver=source->{throw new IOException("Áudio indisponível na origem");};launch();waitFor(()->!player.getPlayWhenReady());click();waitFor(()->((TextView)field("status")).getText().toString().contains("Áudio indisponível na origem"));ins.runOnMainSync(()->{assertFalse(player.getPlayWhenReady());assertFalse(player.isPlaying());assertEquals("previous-local-fixture",player.getCurrentMediaItem().mediaId);});assertTrue(DownloadHistory.report(c).contains("Áudio indisponível na origem"));}
 @Test public void publicIdentityPersistsWithoutTemporaryStreamAndReturnCommandClearsMode()throws Exception{YouTubeAudioPlayback.resolver=source->YouTubeAudio.item(source,"YouTube audio fixture",Uri.fromFile(audio).toString(),"audio/wav");launch();click();waitFor(()->YouTubeAudio.is(player.getCurrentMediaItem())&&player.isPlaying());assertTrue(YouTubeAudio.active(c));assertEquals(SOURCE,YouTubeAudio.saved(c));ins.runOnMainSync(()->player.sendCustomCommand(new SessionCommand(YouTubeAudio.RESTORE,Bundle.EMPTY),Bundle.EMPTY));waitFor(()->!YouTubeAudio.active(c)&&!player.getPlayWhenReady()&&!YouTubeAudio.is(player.getCurrentMediaItem()));ins.runOnMainSync(()->assertFalse(YouTubeAudio.is(player.getCurrentMediaItem())));}
 @Test public void endOfAudioHasOneTapReplayAndDoesNotPersistAnEndBookmark()throws Exception{YouTubeAudioPlayback.resolver=source->YouTubeAudio.item(source,"Replay fixture",Uri.fromFile(audio).toString(),"audio/wav");launch();click();waitFor(()->player.isPlaying()&&YouTubeAudio.is(player.getCurrentMediaItem()));ins.runOnMainSync(()->player.seekTo(player.getDuration()-100));waitFor(()->player.getPlaybackState()==Player.STATE_ENDED&&"Reproduzir áudio novamente".contentEquals(((Button)field("listenAudio")).getText()));waitFor(()->c.getSharedPreferences("youtube_audio",0).getLong("position",-1)==0);ins.runOnMainSync(()->assertEquals("Reproduzir áudio novamente",((Button)unchecked("listenAudio")).getText().toString()));click();waitFor(()->player.isPlaying()&&player.getCurrentPosition()<3000);ins.runOnMainSync(()->assertEquals(SOURCE,YouTubeAudio.source(player.getCurrentMediaItem())));}
 @Test public void actualStreamReadFailureShowsErrorAndKeepsSelectedSource()throws Exception{YouTubeAudioPlayback.resolver=source->YouTubeAudio.item(source,"Missing stream fixture",Uri.fromFile(new File(c.getCacheDir(),"missing-youtube-audio.wav")).toString(),"audio/wav");launch();click();waitFor(()->player.getPlayerError()!=null&&!player.getPlayWhenReady());waitFor(()->((TextView)field("status")).getText().toString().contains("Reprodução do YouTube"));ins.runOnMainSync(()->{assertTrue(YouTubeAudio.is(player.getCurrentMediaItem()));assertEquals(SOURCE,YouTubeAudio.source(player.getCurrentMediaItem()));assertFalse(player.isPlaying());});assertTrue(DownloadHistory.report(c).contains("Reprodução do YouTube"));}

 private Button musicRepeat()throws Exception{Field f=MainActivity.class.getDeclaredField("repeat");f.setAccessible(true);return (Button)f.get(anchor);}
 private void tapMusicRepeat(){ins.runOnMainSync(()->{try{assertTrue(musicRepeat().isEnabled());assertTrue(musicRepeat().performClick());}catch(Exception e){throw new RuntimeException(e);}});}
 @Test public void existingMusicButtonLoopsSelectedYouTubeAudioScreenOffAndCanDisableLoop()throws Exception{
  waitFor(()->anchor.hasWindowFocus()&&musicRepeat().isEnabled());tapMusicRepeat();waitFor(()->player.getRepeatMode()==Player.REPEAT_MODE_ONE);tapMusicRepeat();waitFor(()->player.getRepeatMode()==Player.REPEAT_MODE_ALL);tapMusicRepeat();waitFor(()->player.getRepeatMode()==Player.REPEAT_MODE_OFF);
  YouTubeAudioPlayback.resolver=source->YouTubeAudio.item(source,"Repeat fixture",Uri.fromFile(audio).toString(),"audio/wav");launch();c.getSharedPreferences("music_resume",0).edit().putString("queue","[\"42\"]").putLong("position",12345).putInt("repeat",Player.REPEAT_MODE_ALL).commit();click();waitFor(()->player.isPlaying()&&YouTubeAudio.is(player.getCurrentMediaItem()));ins.runOnMainSync(()->activity.finish());waitFor(()->anchor.hasWindowFocus()&&musicRepeat().isEnabled());tapMusicRepeat();waitFor(()->player.getRepeatMode()==Player.REPEAT_MODE_ONE&&YouTubeAudio.repeat(c,SOURCE)==Player.REPEAT_MODE_ONE);waitFor(()->"↻ 1".contentEquals(musicRepeat().getText()));
  ins.runOnMainSync(()->assertEquals(1f,uncheckedMusicRepeat().getAlpha(),0f));shell("input keyevent 223");ins.runOnMainSync(()->{assertEquals(45000,player.getDuration());player.seekTo(player.getDuration()-150);});waitFor(()->player.isPlaying()&&player.getCurrentPosition()>500&&player.getCurrentPosition()<5000);ins.runOnMainSync(()->{assertFalse(((PowerManager)c.getSystemService(Context.POWER_SERVICE)).isInteractive());assertEquals(Player.REPEAT_MODE_ONE,player.getRepeatMode());assertEquals(SOURCE,YouTubeAudio.source(player.getCurrentMediaItem()));assertEquals(1,player.getMediaItemCount());});assertEquals("[\"42\"]",c.getSharedPreferences("music_resume",0).getString("queue",""));assertEquals(12345,c.getSharedPreferences("music_resume",0).getLong("position",0));assertEquals(Player.REPEAT_MODE_ALL,c.getSharedPreferences("music_resume",0).getInt("repeat",0));
  shell("input keyevent 224");shell("wm dismiss-keyguard");waitFor(()->anchor.hasWindowFocus());tapMusicRepeat();waitFor(()->player.getRepeatMode()==Player.REPEAT_MODE_OFF&&YouTubeAudio.repeat(c,SOURCE)==Player.REPEAT_MODE_OFF);ins.runOnMainSync(()->player.seekTo(player.getDuration()-100));waitFor(()->player.getPlaybackState()==Player.STATE_ENDED);ins.runOnMainSync(()->assertEquals(SOURCE,YouTubeAudio.source(player.getCurrentMediaItem())));
 }
 private Button uncheckedMusicRepeat(){try{return musicRepeat();}catch(Exception e){throw new RuntimeException(e);}}
 @Test public void repeatChoiceSurvivesResolvingSameSourceAgainAndDoesNotFollowAnotherVideo()throws Exception{
  java.util.concurrent.atomic.AtomicInteger resolutions=new java.util.concurrent.atomic.AtomicInteger();YouTubeAudioPlayback.resolver=source->{resolutions.incrementAndGet();return YouTubeAudio.item(source,"Repeat retry fixture",Uri.fromFile(audio).toString(),"audio/wav");};launch();click();waitFor(()->player.isPlaying()&&YouTubeAudio.is(player.getCurrentMediaItem()));ins.runOnMainSync(()->player.setRepeatMode(Player.REPEAT_MODE_ONE));waitFor(()->YouTubeAudio.repeat(c,SOURCE)==Player.REPEAT_MODE_ONE);assertEquals(Player.REPEAT_MODE_OFF,YouTubeAudio.repeat(c,"https://www.youtube.com/watch?v=56xlZcT--xM"));ins.runOnMainSync(()->{player.pause();player.stop();});waitFor(()->!player.getPlayWhenReady()&&player.getPlaybackState()==Player.STATE_IDLE);click();waitFor(()->resolutions.get()==2&&player.isPlaying()&&player.getRepeatMode()==Player.REPEAT_MODE_ONE);assertEquals(Player.REPEAT_MODE_ONE,YouTubeAudio.repeat(c,SOURCE));assertFalse(c.getSharedPreferences("youtube_audio",0).getAll().toString().contains(audio.getAbsolutePath()));YouTubeAudio.clear(c);assertEquals(Player.REPEAT_MODE_OFF,YouTubeAudio.repeat(c,SOURCE));
 }

}
